//! Field / Poseidon helpers — the shared design contract with the ZK track.
//!
//! Everything is BN254 (alt_bn128) with circomlib Poseidon (x^5 S-box,
//! parameters as generated by circomlib / light-poseidon's `new_circom`).
//! All field elements on the wire are 32-byte **big-endian** and must be
//! canonical (`value < Fr modulus`); non-canonical encodings are rejected so
//! that a field element has exactly one byte representation (this is what
//! makes the nullifier PDA seed a sound double-spend key).
//!
//! Contract (must match the circuits exactly):
//! - `nk        = Poseidon(sk, 0)`
//! - `owner_id  = Poseidon(sk, 1)`
//! - `cm        = Poseidon(owner_id, value, blinding)`   (3-input, circuit-side)
//! - `nf        = Poseidon(nk, leaf_index)`              (2-input, circuit-side)
//! - Merkle node = `Poseidon(left, right)`               (2-input, on-chain)
//! - Merkle leaf = `Poseidon(cm, amount)` — the deposit-bound leaf
//!   (re-audit NEW-1): the program computes it at deposit from the
//!   lamports pulled; the circuit recomputes it from the note opening and
//!   the public amount. Depth 20.
//! - Empty-leaf chain: `z[0] = 0`, `z[i+1] = Poseidon(z[i], z[i])`;
//!   the root of the empty tree is `z[20]`.
//!
//! The on-chain program only ever evaluates the 2-input Poseidon (Merkle
//! nodes, the deposit leaf binding, recipient binding). Key/note
//! derivations live inside the circuits.

use anchor_lang::prelude::*;
use ark_ff::{BigInteger, PrimeField};

use crate::errors::DarkError;

/// True iff `bytes` is the canonical big-endian encoding of a BN254 scalar
/// field element (i.e. the value is strictly less than the Fr modulus).
/// Uses groth16-solana's own check so program and verifier agree bit-for-bit.
pub fn is_canonical_field_element(bytes: &[u8; 32]) -> bool {
    groth16_solana::groth16::is_less_than_bn254_field_size_be(bytes)
}

/// circomlib Poseidon over BN254 with exactly two inputs, big-endian in/out.
/// Callers must pass canonical encodings (enforced at the instruction
/// boundary) to keep encodings unique; inputs `>= Fr modulus` are rejected.
///
/// EVALUATION PATH — changed by the Poseidon-cost fix (2026-11-17).
/// This used to evaluate light-poseidon in program code, with parameters
/// built by `crate::poseidon_params` from static tables (themselves a
/// workaround for `get_poseidon_parameters`' 6,336-byte stack frame).
/// Measured on devnet, that software path costs **more than the 1.4M CU
/// per-transaction cap for a single hash**: parameter construction alone
/// is 625,961 CU and one permutation is >773,889 CU, which is why
/// `deposit` (21 hashes) could never execute (W5-NEW-1, second half).
/// `poseidon2` now delegates to the runtime's native `sol_poseidon`
/// syscall through the `solana-poseidon` crate (Bn254 x^5, big-endian):
/// ~819 CU per hash under the syscall cost model.
///
/// The hash VALUES do not change. The syscall computes the identical
/// circomlib Poseidon, and bit-identity against the previous
/// implementation was proven on devnet before this change landed: the
/// KAT below, the full depth-20 zero chain, the modulus-1 boundary
/// pairs, and 200 randomized canonical pairs all match bit-for-bit,
/// and both implementations reject inputs `>= Fr modulus`
/// (`InputLargerThanModulus`). Full record:
/// `dark-protocol/docs/POSEIDON-COST.md`. On host (unit tests) the
/// `solana-poseidon` crate evaluates the same function in software via
/// its own light-poseidon fallback, so the host suite below still pins
/// the values. `crate::poseidon_params` is retained as the parameter
/// provenance record; nothing calls it at runtime anymore.
pub fn poseidon2(a: &[u8; 32], b: &[u8; 32]) -> Result<[u8; 32]> {
    let out = solana_poseidon::hashv(
        solana_poseidon::Parameters::Bn254X5,
        solana_poseidon::Endianness::BigEndian,
        &[a, b],
    )
    .map_err(|_| error!(DarkError::PoseidonError))?;
    Ok(out.to_bytes())
}

/// RECIPIENT ENCODING v1 (program-defined; the ZK track's README supersedes
/// this when it lands — see vk.rs / FINDINGS-MAP.md):
///
/// A Solana pubkey is 32 bytes. Split it into two 16-byte big-endian limbs
/// `hi = pubkey[0..16]`, `lo = pubkey[16..32]`. Each limb is `< 2^128`, hence
/// a canonical field element when zero-extended to 32 bytes. The recipient
/// public input is `recipient_field = Poseidon(hi, lo)`.
///
/// The withdraw handler computes this from the *actual recipient account in
/// the transaction*, so a proof is bound to the payee and cannot be replayed
/// to pay anyone else.
pub fn recipient_field(recipient: &Pubkey) -> Result<[u8; 32]> {
    let bytes = recipient.to_bytes();
    let mut hi = [0u8; 32];
    let mut lo = [0u8; 32];
    hi[16..].copy_from_slice(&bytes[..16]);
    lo[16..].copy_from_slice(&bytes[16..]);
    poseidon2(&hi, &lo)
}

/// Encode a lamport amount as a public-input field element (big-endian,
/// value in the low 8 bytes). Always canonical.
pub fn amount_to_field(amount: u64) -> [u8; 32] {
    let mut out = [0u8; 32];
    out[24..].copy_from_slice(&amount.to_be_bytes());
    out
}

/// Negate proof A of a Groth16 proof.
///
/// groth16-solana's pairing equation is arranged so that the caller must
/// supply `-A`. A G1 point `(x, y)` negates to `(x, -y)` over the base field
/// Fq, so this is pure Fq arithmetic on the big-endian y-coordinate
/// (`proof[32..64]`); x is untouched. An off-curve or non-canonical A simply
/// fails later inside the pairing syscall — fail-closed either way.
pub fn negate_proof_a(proof: &[u8; 256]) -> [u8; 64] {
    let mut a = [0u8; 64];
    a.copy_from_slice(&proof[0..64]);
    let y = ark_bn254::Fq::from_be_bytes_mod_order(&a[32..64]);
    let neg_y = -y;
    let be = neg_y.into_bigint().to_bytes_be();
    a[32..64].copy_from_slice(&be);
    a
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn poseidon2_known_answer_from_light_poseidon_docs() {
        // Worked example printed in light-poseidon 0.2's own documentation:
        // hash_bytes_be of [0x01;32] and [0x02;32].
        let out = poseidon2(&[1u8; 32], &[2u8; 32]).unwrap();
        let expected: [u8; 32] = [
            13, 84, 225, 147, 143, 138, 140, 28, 125, 235, 94, 3, 85, 242, 99, 25, 32, 123, 132,
            254, 156, 162, 206, 27, 38, 231, 53, 200, 41, 130, 25, 144,
        ];
        assert_eq!(out, expected);
    }

    #[test]
    fn canonical_check_rejects_modulus_and_above() {
        // Fr modulus, big-endian:
        // 21888242871839275222246405745257275088548364400416034343698204186575808495617
        let modulus: [u8; 32] = [
            0x30, 0x64, 0x4e, 0x72, 0xe1, 0x31, 0xa0, 0x29, 0xb8, 0x50, 0x45, 0xb6, 0x81, 0x81,
            0x58, 0x5d, 0x97, 0x81, 0x6a, 0x91, 0x68, 0x71, 0xca, 0x8d, 0x3c, 0x20, 0x8c, 0x16,
            0xd8, 0x7c, 0xfd, 0x47,
        ];
        assert!(!is_canonical_field_element(&modulus));
        assert!(!is_canonical_field_element(&[0xffu8; 32]));
        assert!(is_canonical_field_element(&[0u8; 32]));
        let mut one = [0u8; 32];
        one[31] = 1;
        assert!(is_canonical_field_element(&one));
    }

    #[test]
    fn negate_proof_a_is_an_involution_and_keeps_x() {
        let mut proof = [0u8; 256];
        // G1 generator (1, 2) as proof A.
        proof[31] = 1;
        proof[63] = 2;
        let neg = negate_proof_a(&proof);
        assert_eq!(&neg[0..32], &proof[0..32]); // x unchanged
        assert_ne!(&neg[32..64], &proof[32..64]); // y -> p - 2
        // Negating again returns the original point.
        let mut proof2 = [0u8; 256];
        proof2[0..64].copy_from_slice(&neg);
        let back = negate_proof_a(&proof2);
        assert_eq!(&back[..], &proof[0..64]);
    }

    #[test]
    fn recipient_field_is_deterministic_and_key_bound() {
        let k1 = Pubkey::new_unique();
        let k2 = Pubkey::new_unique();
        let f1 = recipient_field(&k1).unwrap();
        assert_eq!(f1, recipient_field(&k1).unwrap());
        assert_ne!(f1, recipient_field(&k2).unwrap());
        assert!(is_canonical_field_element(&f1));
    }

    #[test]
    fn amount_field_encoding() {
        let f = amount_to_field(1_000_000_000);
        assert_eq!(&f[24..], &1_000_000_000u64.to_be_bytes());
        assert!(is_canonical_field_element(&f));
        assert_eq!(amount_to_field(0), [0u8; 32]);
    }
}
